using MetaheuristicsPlatform.Parameters;
namespace MetaheuristicsPlatform.Algorithms.Constraints.EpsilonConstrainedDe;
public sealed class EpsilonConstrainedDeParameters : IMetaheuristicParameters
{ public int PopulationSize { get; init; }=80; public int MaximumGenerations { get; init; }=200; public double DifferentialWeight { get; init; }=0.5; public double CrossoverProbability { get; init; }=0.9; public double InitialEpsilonQuantile { get; init; }=0.2; public int EpsilonControlGenerations { get; init; }=120; public double EpsilonExponent { get; init; }=5.0; public void Validate(){if(PopulationSize<4)throw new ArgumentOutOfRangeException(nameof(PopulationSize));if(MaximumGenerations<=0)throw new ArgumentOutOfRangeException(nameof(MaximumGenerations));if(!double.IsFinite(DifferentialWeight)||DifferentialWeight<=0.0)throw new ArgumentOutOfRangeException(nameof(DifferentialWeight));if(!double.IsFinite(CrossoverProbability)||CrossoverProbability<0.0||CrossoverProbability>1.0)throw new ArgumentOutOfRangeException(nameof(CrossoverProbability));if(!double.IsFinite(InitialEpsilonQuantile)||InitialEpsilonQuantile<0.0||InitialEpsilonQuantile>1.0)throw new ArgumentOutOfRangeException(nameof(InitialEpsilonQuantile));if(EpsilonControlGenerations<=0)throw new ArgumentOutOfRangeException(nameof(EpsilonControlGenerations));if(!double.IsFinite(EpsilonExponent)||EpsilonExponent<=0.0)throw new ArgumentOutOfRangeException(nameof(EpsilonExponent));} }
